import{_ as e,c as a,o as r,a2 as o}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"Formatos compatibles","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/formats.md","filePath":"es/guide/formats.md","lastUpdated":1793163976000}'),n={name:"es/guide/formats.md"};function i(s,t,l,d,c,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="formatos-compatibles" tabindex="-1">Formatos compatibles <a class="header-anchor" href="#formatos-compatibles" aria-label="Permalink to &quot;Formatos compatibles&quot;">​</a></h1><p>NueZip es compatible con una amplia gama de formatos de archivo tanto para lectura como para escritura. A continuación se muestra la matriz completa de compatibilidad de formatos.</p><h2 id="matriz-de-formatos" tabindex="-1">Matriz de formatos <a class="header-anchor" href="#matriz-de-formatos" aria-label="Permalink to &quot;Matriz de formatos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Formato</th><th style="text-align:center;">Lectura</th><th style="text-align:center;">Escritura (comprimir)</th><th style="text-align:center;">Cifrado</th><th style="text-align:center;">Multi-volumen</th></tr></thead><tbody><tr><td><strong>ZIP</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256</td><td style="text-align:center;">✅</td></tr><tr><td><strong>7-Zip (.7z)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">AES-256 (LZMA2)</td><td style="text-align:center;">✅</td></tr><tr><td><strong>TAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">✅</td></tr><tr><td><strong>GZIP (.gz)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>BZIP2 (.bz2)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>XZ</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>Zstandard (.zst)</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td></tr><tr><td><strong>RAR</strong></td><td style="text-align:center;">✅</td><td style="text-align:center;">❌</td><td style="text-align:center;">✅ (lectura)</td><td style="text-align:center;">✅ (lectura)</td></tr></tbody></table><blockquote><p><strong>Nota</strong>: La compresión RAR no es compatible debido a restricciones de licencia. NueZip puede leer archivos RAR, incluidos los archivos RAR multi-volumen y cifrados.</p></blockquote><h2 id="detalles-de-formatos" tabindex="-1">Detalles de formatos <a class="header-anchor" href="#detalles-de-formatos" aria-label="Permalink to &quot;Detalles de formatos&quot;">​</a></h2><h3 id="zip" tabindex="-1">ZIP <a class="header-anchor" href="#zip" aria-label="Permalink to &quot;ZIP&quot;">​</a></h3><ul><li><strong>Compresión</strong>: Store, Deflate, Deflate64, BZIP2, LZMA, PPMd</li><li><strong>Cifrado</strong>: AES-256 (recomendado), ZipCrypto (heredado)</li><li><strong>Soporte de volúmenes</strong>: Archivos divididos multi-volumen (<code>.zip.001</code>, <code>.zip.002</code>, ...)</li><li><strong>Ideal para</strong>: Compatibilidad universal entre plataformas</li></ul><h3 id="_7-zip" tabindex="-1">7-Zip <a class="header-anchor" href="#_7-zip" aria-label="Permalink to &quot;7-Zip&quot;">​</a></h3><ul><li><strong>Compresión</strong>: LZMA2 (predeterminado), LZMA, PPMd, BZIP2, Deflate</li><li><strong>Cifrado</strong>: AES-256</li><li><strong>Soporte de volúmenes</strong>: Archivos divididos multi-volumen</li><li><strong>Ideal para</strong>: Máxima relación de compresión</li></ul><h3 id="tar" tabindex="-1">TAR <a class="header-anchor" href="#tar" aria-label="Permalink to &quot;TAR&quot;">​</a></h3><ul><li><strong>Compresión</strong>: Sin comprimir, o combinado con GZIP/BZIP2/XZ/Zstandard</li><li><strong>Ideal para</strong>: Archivos de Unix/Linux, preservando permisos de archivos</li></ul><h3 id="gzip-bzip2-xz-zstandard" tabindex="-1">GZIP / BZIP2 / XZ / Zstandard <a class="header-anchor" href="#gzip-bzip2-xz-zstandard" aria-label="Permalink to &quot;GZIP / BZIP2 / XZ / Zstandard&quot;">​</a></h3><ul><li>Formatos de compresión <strong>independientes</strong> (un solo archivo, sin agrupación en archivo)</li><li>A menudo se usan en combinación con TAR (<code>.tar.gz</code>, <code>.tar.xz</code>, <code>.tar.zst</code>)</li></ul><h3 id="rar" tabindex="-1">RAR <a class="header-anchor" href="#rar" aria-label="Permalink to &quot;RAR&quot;">​</a></h3><ul><li><strong>Soporte de lectura</strong>: RAR4, RAR5, multi-volumen, cifrado</li><li><strong>Reparación</strong>: Registro de recuperación y reconstrucción</li><li><strong>Escritura</strong>: No compatible</li></ul><h2 id="consejos" tabindex="-1">Consejos <a class="header-anchor" href="#consejos" aria-label="Permalink to &quot;Consejos&quot;">​</a></h2><ul><li><strong>Para compartir con otros</strong>: Usa <strong>ZIP</strong> — es el formato más ampliamente compatible</li><li><strong>Para archivo personal</strong>: Usa <strong>7-Zip</strong> — mejores relaciones de compresión, ahorra espacio en disco</li><li><strong>Para archivos grandes</strong>: Usa <strong>ZIP dividido</strong> o <strong>7-Zip dividido</strong> para dividir en volúmenes manejables</li><li><strong>Para datos sensibles</strong>: Activa siempre el <strong>cifrado AES-256</strong> con una contraseña robusta</li></ul>',18)])])}const u=e(n,[["render",i]]);export{p as __pageData,u as default};
